import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.logging.Logger;
import java.util.regex.Pattern;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final Pattern ALPHA_NUM = Pattern.compile("^[a-zA-Z0-9_]+$");

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {

        String reportId = req.getParameter("id");
        String sortCol = req.getParameter("sort");
        String direction = req.getParameter("dir");
        String fiscal = req.getParameter("fiscal_year");

        // Validate report ID strictly
        if (reportId == null || !ALPHA_NUM.matcher(reportId).matches()) {
            resp.sendError(400, "Invalid report ID");
            return;
        }

        // Validate sort direction
        if (direction == null) direction = "ASC";
        if (!direction.equalsIgnoreCase("ASC") && !direction.equalsIgnoreCase("DESC")) {
            direction = "ASC";
        }

        // Validate sort column against allowlist
        String[] allowedCols = {"created_at", "amount", "department", "status"};
        boolean validSort = false;
        if (sortCol != null) {
            for (String col : allowedCols) {
                if (col.equals(sortCol)) { validSort = true; break; }
            }
        }
        if (!validSort) sortCol = "created_at";

        // fiscal_year filter - expected format: "2023" or "2023-2024"
        // We use parameterized portion for the main query
        String baseQuery = "SELECT r.id, r.created_at, r.amount, r.department, r.status " +
                          "FROM reports r WHERE r.report_type = ? ";

        // Dynamic fiscal year filter construction
        String fiscalFilter = "";
        if (fiscal != null && !fiscal.isEmpty()) {
            // Developer note: fiscal_year comes from a dropdown in the UI,
            // values are like "2023" or "2023-2024". We build the filter inline
            // since PreparedStatement doesn't support dynamic IN clauses easily.
            fiscalFilter = "AND r.fiscal_year IN ('" + fiscal + "') ";
        }

        String orderClause = "ORDER BY r." + sortCol + " " + direction;
        String fullQuery = baseQuery + fiscalFilter + orderClause;

        log.info("Executing report query for type: " + reportId);

        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement(fullQuery)) {

            ps.setString(1, reportId);

            ResultSet rs = ps.executeQuery();
            resp.setContentType("application/json");
            var writer = resp.getWriter();
            writer.write("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) writer.write(",\n");
                writer.write(String.format(
                    "{\"id\":\"%s\",\"created_at\":\"%s\",\"amount\":%s,\"department\":\"%s\",\"status\":\"%s\"}",
                    rs.getString("id"),
                    rs.getString("created_at"),
                    rs.getBigDecimal("amount"),
                    rs.getString("department"),
                    rs.getString("status")
                ));
                first = false;
            }
            writer.write("\n]");
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }
}
